def IM(f, alt, cap, cred, url):
    """Picture fields for a feed item, board row or section. f = file under mars/img/ (at most 1000 px wide, JPEG). cred names the author and the license; url = the page where the license was read."""
    return dict(image="img/" + f, image_alt=alt, image_caption=cap, image_credit=cred, image_url=url)
